SELECT DATE_TRUNC('MONTH', sale_date) AS activity_month, CASE WHEN revenue >= 3600 THEN 'HIGH' ELSE 'LOW' END AS revenue_tier, DATE_TRUNC('QUARTER', sale_date) AS quarter_start, APPROX_PERCENTILE(revenue, ARRAY(0.25, 0.5, 0.75)) AS revenue_quartiles, BIT_AND(units) AS units_bit_and, APPROX_PERCENTILE(units, ARRAY(0.25, 0.5, 0.75)) AS units_quartiles, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('MONTH', sale_date) ORDER BY BIT_AND(units) DESC) AS units_bit_and_dense_rank FROM store_sales GROUP BY DATE_TRUNC('MONTH', sale_date), CASE WHEN revenue >= 3600 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('QUARTER', sale_date)
